#!/usr/bin/env Rscript
#
# Generates research/papers.yml and research/datasets.yml from the Zotero
# Better CSL JSON export. Runs automatically as a Quarto pre-render step.
#
# DO NOT edit the generated YAML by hand — edit the item in Zotero instead.
# Zotero is the single source of truth; see CONTRIBUTING.md for the tag scheme.
#
# Zotero setup (once):
#   1. Create a collection "CHF Outputs".
#   2. Right-click → Export Collection → Better CSL JSON, tick "Keep updated",
#      save as research/zotero-outputs.json
#   3. Repeat with Better BibTeX → research/chf-outputs.bib (used for citations
#      inside Insights posts).
#
# Tags that matter:
#   chf:public              only tagged items reach the website
#   project:<Theme>         assigns an output to a research theme
#   status:working-paper    drives the badge
#   status:published
#
# Links under each abstract (rendered by research/papers.ejs):
#   working paper           URL, else DOI ("Working paper")
#   published               DOI ("Published version") and URL ("Preprint"), plus a
#                           venue line from the journal, volume, issue and pages

suppressPackageStartupMessages({
  library(jsonlite)
  library(yaml)
})

`%||%` <- function(x, y) if (is.null(x) || !length(x)) y else x

src <- "research/zotero-outputs.json"

# A failing pre-render script takes the whole site down. A missing Zotero export
# is a normal state (a fresh clone, or before the collection exists), so exit
# cleanly and leave any previously generated YAML in place.
if (!file.exists(src)) {
  message("build-research.R: ", src, " not found — leaving existing YAML in place.")
  quit(status = 0)
}

items <- jsonlite::fromJSON(src, simplifyVector = FALSE)

kw <- function(it) trimws(strsplit(it$keyword %||% "", ",")[[1]])

tagged <- function(it, prefix) {
  sub(paste0("^", prefix), "", grep(paste0("^", prefix), kw(it), value = TRUE))
}

authors <- function(it) {
  vapply(it$author %||% list(),
         function(a) trimws(paste(a$given %||% "", a$family %||% a$literal %||% "")),
         character(1))
}

year <- function(it) {
  p <- tryCatch(it$issued$`date-parts`[[1]][[1]], error = function(e) NULL)
  if (is.null(p) || is.na(p)) NULL else as.character(p)
}

byline <- function(a) {
  if (length(a) <= 2) return(paste(a, collapse = " and "))
  paste0(paste(head(a, -1), collapse = ", "), ", and ", tail(a, 1))
}

is_published <- function(it) "published" %in% tagged(it, "status:")

# A paper hosted on this site (research/papers/) carries its full public URL in
# Zotero. Strip the domain so the link also works in a local preview.
local_url <- function(url) {
  if (is.null(url)) return(NULL)
  sub("^https?://(www\\.)?householdfinance\\.org\\.za(?=/)", "", url, perl = TRUE)
}

# Once a paper is published, the DOI is the version of record and the URL field
# holds the preprint. Before that, whichever of the two exists is the working
# paper (an arXiv DOI is a preprint DOI, not a publication).
links <- function(it) {
  doi <- if (!is.null(it$DOI)) paste0("https://doi.org/", it$DOI)
  url <- local_url(it$URL)
  out <- if (is_published(it)) {
    list(
      if (!is.null(doi %||% url)) list(label = "Published version", url = doi %||% url),
      if (!is.null(doi) && !is.null(url) && url != doi) list(label = "Preprint", url = url)
    )
  } else {
    list(if (!is.null(url %||% doi)) list(label = "Working paper", url = url %||% doi))
  }
  Filter(Negate(is.null), out)
}

venue <- function(it) {
  if (!is_published(it) || is.null(it$`container-title`)) return(NULL)
  vol <- paste0(it$volume %||% "", if (!is.null(it$issue)) sprintf(" (%s)", it$issue) else "")
  parts <- c(sprintf("<em>%s</em>%s", it$`container-title`,
                     if (nzchar(vol)) paste0(" ", vol) else ""),
             year(it),
             if (!is.null(it$page)) paste0("pp. ", gsub("-", "–", it$page)))
  paste0(paste(parts, collapse = ", "), ".")
}

# Empty fields are dropped rather than written as `~`.
to_entry <- function(it) {
  status <- tagged(it, "status:")
  Filter(function(x) !is.null(x) && length(x), list(
    title       = it$title %||% "Untitled",
    author      = as.list(authors(it)),
    byline      = byline(authors(it)),
    date        = year(it),
    categories  = as.list(tagged(it, "project:")),
    status      = if (length(status)) gsub("-", " ", status[1]),
    venue       = venue(it),
    description = it$abstract,
    chf_links   = links(it)
  ))
}

public  <- Filter(function(it) "chf:public" %in% kw(it), items)
is_data <- function(it) identical(it$type, "dataset")

write_yaml_file <- function(x, path) {
  writeLines(
    c("# GENERATED by scripts/build-research.R from Zotero. DO NOT EDIT.",
      "# Edit the item in the Zotero collection \"CHF Outputs\" instead.",
      yaml::as.yaml(x)),
    path
  )
  message("build-research.R: wrote ", length(x), " entries to ", path)
}

write_yaml_file(lapply(Filter(Negate(is_data), public), to_entry), "research/papers.yml")
write_yaml_file(lapply(Filter(is_data,         public), to_entry), "research/datasets.yml")
